<script>
function bookingForm(){return {zoneId:'{{ request('zone', old('pc_zone_id')) }}',pcId:'{{ old('pc_id') }}',startsAt:'',duration:'60',pcs:[],privateZone:false,status:'',init(){if(this.zoneId)this.loadAvailability()},async loadAvailability(){this.privateZone=false;this.pcs=[];this.pcId='';const option=document.querySelector('[name="pc_zone_id"] option:checked');this.privateZone=option?.dataset.mode==='private_room';if(!this.zoneId||this.privateZone||!this.startsAt)return;this.status='Checking PC availability…';try{const url=new URL('{{ route('account.bookings.availability') }}',window.location.origin);url.searchParams.set('zone_id',this.zoneId);url.searchParams.set('starts_at',this.startsAt);url.searchParams.set('duration_minutes',this.duration);const response=await fetch(url,{headers:{'Accept':'application/json'}});const data=await response.json();this.pcs=data.pcs||[];this.status=this.pcs.length?'Available PCs updated.':'No PCs are available at that time.'}catch(e){this.status='Could not check availability. Staff will verify your request.'}}}}
</script>
